import{_ as t,o,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-07-22 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-07-22 :: Ceph Orchestration Meeting","date":"2019-07-22T00:00:00.000Z","updated":"2019-07-24T00:00:00.000Z","tags":["Ceph","会议纪要","Rook","存储卷","动态存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-07-22_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-07-22_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),s={name:"posts/2019/2019-07-22_-_-_Ceph_Orchestration_Meeting.md"};function l(n,e,a,p,_,g){return o(),i("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年某日</p><p><strong>参会人员</strong>： 众人（具体姓名未提及）</p><p><strong>会议内容</strong>：</p><p><strong>一、Kieffer 驱动集成改进</strong></p><ul><li>主要集中在改进 Kieffer 驱动集成，以提升性能和稳定性。</li></ul><p><strong>二、Ceph 14.2 版本相关</strong></p><ul><li>14.2 版本已修复了 NFS Kinshasa 打包问题，由 Thomas 解决。</li><li>14.2 版本的镜像正在重建中，旨在为 Rook 1.1 版本提供基础。</li><li>如果 14.3 版本发布时间较长，则可能使用 14.2 版本与 Rook 1.1 版本一同发布。</li></ul><p><strong>三、动态存储卷问题</strong></p><ul><li>在 AWS 环境中尝试在 TV 设备上运行 OSD，而不是传统的 /dev 下的原始设备。</li><li>使用 <code>set volume</code> 配置 PV 时，由于设备挂载方式不同，导致无法找到大小属性，设置失败。</li><li>已与 Alfredo 开启线程讨论该问题，但尚未创建跟踪问题。</li><li>建议创建一个 Red Hat 集成的跟踪问题，以便进一步跟踪。</li></ul><p><strong>四、其他事项</strong></p><ul><li>合并了由 so-meager 提交的 ant-eww 创建的 PR。</li><li>尝试使用 diamond 工具，但需要先完成其他工作。</li></ul><p><strong>五、行动计划</strong></p><ul><li>继续改进 Kieffer 驱动集成。</li><li>关注 14.2 版本及 Rook 1.1 版本发布。</li><li>解决动态存储卷问题，并创建跟踪问题。</li><li>完成其他待办事项。</li></ul><p><strong>会议总结</strong>： 本次会议讨论了 Ceph 14.2 版本的修复情况、Kieffer 驱动集成改进以及动态存储卷问题。会议确定了后续行动计划，包括改进 Kieffer 驱动、关注版本发布、解决问题并创建跟踪问题。</p>',15)])])}const h=t(s,[["render",l]]);export{c as __pageData,h as default};
